package com.vandorlabs.neoforge.trapdoor;
import com.google.gson.*;
import com.vandorlabs.render.TrapdoorLeafPose;
import java.nio.file.*;
public final class TrapdoorGeometryChecks {
 private static JsonElement field(JsonObject row,String key){return row.has(key)?row.get(key):JsonNull.INSTANCE;}
 private static boolean bool(JsonObject row,String name){return row.get(name).getAsBoolean();}
 private static double number(JsonObject row,String name){return row.get(name).getAsDouble();}
 private static void same(double actual,double expected,String label,int profile){if(Double.doubleToRawLongBits(actual)!=Double.doubleToRawLongBits(expected))throw new AssertionError(label+" profile="+profile+" actual="+actual+" expected="+expected);}
 public static void main(String[] args)throws Exception{int profiles=0,collisions=0,rays=0,differences=0;double[][] corner=new double[8][3];double[] hit=new double[4];NativeTrapdoorGeometry.Snapshot dense=null;TrapdoorLeafPose densePose=null;try(var stream=Files.lines(Path.of(args[0]))){for(String line:(Iterable<String>)stream::iterator){var row=JsonParser.parseString(line).getAsJsonObject();var pose=new TrapdoorLeafPose(bool(row,"diagonal"),row.get("position").getAsInt(),row.get("turns").getAsInt(),bool(row,"inverted"),bool(row,"sliding"),bool(row,"cover"),bool(row,"surface"),bool(row,"intoWall"),bool(row,"reverse"),bool(row,"closedReverse"),row.get("lift").getAsInt(),number(row,"hinge"),number(row,"travel"),number(row,"overhang"));double[] phases={0,.125,.5,.875,1};var expectedCorners=row.getAsJsonArray("corners");for(int phase=0;phase<phases.length;phase++){pose.write(phases[phase],false,corner);var expected=expectedCorners.get(phase).getAsJsonArray();for(int v=0;v<8;v++)for(int axis=0;axis<3;axis++)same(corner[v][axis],expected.get(v).getAsJsonArray().get(axis).getAsDouble(),"Actual source visual corner",profiles);}var origin=row.getAsJsonArray("origin");double ox=origin.get(0).getAsDouble(),oy=origin.get(1).getAsDouble(),oz=origin.get(2).getAsDouble();
  for(var element:row.getAsJsonArray("endpoints")){var endpoint=element.getAsJsonObject();var snapshot=NativeTrapdoorGeometry.snapshot(pose,bool(endpoint,"open"));var bounds=endpoint.getAsJsonArray("bounds");double[] actualBounds={snapshot.bounds().minX,snapshot.bounds().minY,snapshot.bounds().minZ,snapshot.bounds().maxX,snapshot.bounds().maxY,snapshot.bounds().maxZ};for(int axis=0;axis<6;axis++)same(actualBounds[axis],bounds.get(axis).getAsDouble(),"Actual block bounds",profiles);var boxes=endpoint.getAsJsonArray("collision");if(boxes.size()!=snapshot.collisionCount())throw new AssertionError("Collision count profile="+profiles);for(int box=0;box<boxes.size();box++){var b=snapshot.collision(box);double[] coords={b.minX+ox,b.minY+oy,b.minZ+oz,b.maxX+ox,b.maxY+oy,b.maxZ+oz};for(int axis=0;axis<6;axis++)same(coords[axis],boxes.get(box).getAsJsonArray().get(axis).getAsDouble(),"Actual collision slice",profiles);collisions++;}if(snapshot.collisionCount()==256){dense=snapshot;densePose=pose;}
   for(var traceElement:endpoint.getAsJsonArray("rays")){var trace=traceElement.getAsJsonObject();var start=trace.getAsJsonArray("start");var end=trace.getAsJsonArray("end");if(!field(trace,"block").equals(field(trace,"offset")))differences++;for(boolean offset:new boolean[]{false,true}){var expected=field(trace,offset?"offset":"block");boolean found=snapshot.trace(offset,ox,oy,oz,start.get(0).getAsDouble(),start.get(1).getAsDouble(),start.get(2).getAsDouble(),end.get(0).getAsDouble(),end.get(1).getAsDouble(),end.get(2).getAsDouble(),hit);if(found==expected.isJsonNull())throw new AssertionError("Actual source ray presence profile="+profiles+" offset="+offset+" actual="+found+" expected="+expected);if(found){var point=expected.getAsJsonObject().getAsJsonArray("point");for(int axis=0;axis<3;axis++)same(hit[axis],point.get(axis).getAsDouble(),"Actual ray hit",profiles);same(hit[3],expected.getAsJsonObject().get("face").getAsDouble(),"Actual ray face/tie",profiles);}rays++;}}
  }profiles++;
 }}if(profiles!=768||collisions!=59136||rays!=49152||differences!=72)throw new AssertionError("Complete geometry matrix "+profiles+"/"+collisions+"/"+rays+"/"+differences);if(dense==null)throw new AssertionError("Dense diagonal fixture");var sink=new Edges();for(int i=0;i<20000;i++)NativeTrapdoorGeometry.snapshot(densePose,true).outline(sink);var meter=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();meter.setThreadAllocatedMemoryEnabled(true);long thread=Thread.currentThread().threadId(),before=meter.getThreadAllocatedBytes(thread);sink.edges=0;for(int i=0;i<4096;i++)NativeTrapdoorGeometry.snapshot(densePose,true).outline(sink);long allocated=meter.getThreadAllocatedBytes(thread)-before;if(sink.edges!=4096*12||allocated!=0)throw new AssertionError("Dense outline allocation/edge bound "+sink.edges+"/"+allocated);if(NativeTrapdoorGeometry.retainedBytes()>8*1024*1024)throw new AssertionError("Geometry byte budget");System.out.println("[vandorlabs][trapdoor-geometry] CPU PASS actualForge profiles="+profiles+" collisionBoxes="+collisions+" rays="+rays+" distinctblock/offset="+differences+" denseOutline4096queries=49152edges/0allocated; no mesh tessellation");
 }
 private static final class Edges implements com.vandorlabs.render.TrapdoorLeafSnapshot.EdgeSink {long edges;double consumed;public void edge(double ax,double ay,double az,double bx,double by,double bz){edges++;consumed+=ax+ay+az+bx+by+bz;}}
}
